contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId) public payable {
        require(true);
        uint256 count = c.uniqueTokensOutstanding();
        require(tokenId >= count);

        bool reverted;
        c.safeTransferFrom(address(this), address(this), tokenId, 1, bytes(""));
        reverted = false;

        assert(!(tokenId >= c.uniqueTokensOutstanding()) || reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 amount) public payable {
        require(tokenId >= c.uniqueTokensOutstanding());
        require(!c.allowedBurningAddresses(address(this)));

        // create the token so balanceOf is well-defined (test contract is owner/admin)
        c.createGameItem("t", "u", false, true, 0, 0, 1);

        uint256 balBefore = c.balanceOf(address(this), tokenId);
        require(balBefore >= amount);

        bool reverted;
        try c.burn(address(this), tokenId, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this), tokenId);
        assert(reverted && balAfter == balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address admin, bool access) public payable {
        require(admin != address(this));
        bool before = c.isAdmin(admin);
        bool reverted;
        try c.adjustAdminAccess(admin, access) { reverted = false; } catch { reverted = true; }
        bool after = c.isAdmin(admin);
        assert(reverted && after == before);
    }
    receive() external payable {}
}

