contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory tokenURI) public payable {
        require(bytes(tokenURI).length > 0);
        uint256 before = c.uniqueTokensOutstanding();
        c.createGameItem("item", tokenURI, false, false, 1, 1, 1);
        uint256 afterCount = c.uniqueTokensOutstanding();
        string memory returned = c.uri(before);
        assert(afterCount == before + 1 && keccak256(bytes(returned)) == keccak256(bytes(tokenURI)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 itemsRemaining) public payable {
        require(itemsRemaining > 0);
        uint256 before = c.uniqueTokensOutstanding();
        c.createGameItem("item", "", true, true, itemsRemaining, 1, 1);
        uint256 afterCount = c.uniqueTokensOutstanding();
        uint256 supply = c.remainingSupply(before);
        assert(afterCount == before + 1 && supply == itemsRemaining);
    }
    receive() external payable {}
}
